#!/usr/bin/env python3
"""Audit a Pi/Feynman JSONL session for observability + artifact evidence.

Usage: python3 audit.py <session.jsonl> [--json out.json]
Prints tool-call counts, message roles, token usage, artifact paths mentioned,
and integrity vocabulary counts. Read-only.
"""
import json, sys, re, collections, os

def walk(obj, acc):
    if isinstance(obj, dict):
        for k, v in obj.items():
            if k in ("content", "text", "message", "summary", "output") and isinstance(v, (str, list, dict)):
                acc.append((k, v))
            walk(v, acc)
    elif isinstance(obj, list):
        for v in obj:
            walk(v, acc)

def texts(v):
    if isinstance(v, str):
        return [v]
    if isinstance(v, list):
        out = []
        for x in v:
            out += texts(x)
        return out
    if isinstance(v, dict):
        out = []
        for k in ("text", "content", "thinking"):
            if k in v:
                out += texts(v[k])
        return out
    return []

def main():
    path = sys.argv[1]
    outpath = None
    if "--json" in sys.argv:
        outpath = sys.argv[sys.argv.index("--json") + 1]
    rows, tools, roles, usage = [], collections.Counter(), collections.Counter(), collections.Counter()
    tool_errors = 0
    paths = set()
    all_text = []
    with open(path, encoding="utf-8", errors="replace") as f:
        for line in f:
            line = line.strip()
            if not line:
                continue
            try:
                ev = json.loads(line)
            except json.JSONDecodeError:
                continue
            rows.append(ev)
            typ = ev.get("type")
            if typ == "message":
                msg = ev.get("message", {})
                role = msg.get("role", "?")
                roles[role] += 1
                for u in msg.get("usage", {}) or {}:
                    if isinstance(msg["usage"][u], (int, float)):
                        usage[u] += msg["usage"][u]
                acc = []
                walk(msg, acc)
                for _, v in acc:
                    all_text += texts(v)
                content = msg.get("content")
                if isinstance(content, list):
                    for part in content:
                        if isinstance(part, dict) and part.get("type") == "toolCall":
                            name = part.get("name") or part.get("toolName") or "?"
                            tools[name] += 1
                            args = part.get("arguments") or {}
                            if isinstance(args, dict) and isinstance(args.get("path"), str):
                                paths.add(args["path"])
                        elif isinstance(part, dict) and part.get("type") == "toolResult":
                            if part.get("isError") or part.get("error"):
                                tool_errors += 1
            elif typ == "tool":
                name = ev.get("toolName") or ev.get("name") or "?"
                tools[name] += 1
                if ev.get("isError"):
                    tool_errors += 1
    joined = "\n".join(all_text)
    vocab = {w: len(re.findall(r"\b" + w + r"\b", joined, re.I))
             for w in ["verified", "confirmed", "reproduced", "blocked", "unverified", "inferred", "TODO"]}
    cited = len(re.findall(r"https?://[^\s)\]]+", joined))
    result = {
        "session": os.path.basename(path),
        "events": len(rows),
        "roles": dict(roles),
        "tool_calls_total": sum(tools.values()),
        "tool_calls": dict(tools.most_common()),
        "tool_errors": tool_errors,
        "usage": dict(usage),
        "unique_tool_paths": len(paths),
        "distinct_urls_in_transcript": cited,
        "integrity_vocab": vocab,
        "event_types": dict(collections.Counter(r.get("type") for r in rows)),
    }
    print(json.dumps(result, indent=2))
    if outpath:
        with open(outpath, "w") as f:
            json.dump(result, f, indent=2)

if __name__ == "__main__":
    main()
